"use strict";

// Depends on its OWN nested copy of fixture-lib -- a second installed
// PackageInstance with the same name and the same version as the top-level
// one. Its `parse` export is genuine, attributable and genuinely called,
// which is the point: if export attribution ever borrowed a candidate
// across instances, the top-level instance's unattributable `parse` would
// pick this reachable one up and report AFFECTED off the wrong install.
const lib = require("fixture-lib");

module.exports = function run(input) {
  return lib.parse(input);
};
